class Solution {
    public int maximumChocolates(int r, int c, int[][] grid) {
        int[][][] dp = new int[r][c][c];
        for (int col1 = 0; col1 < c; col1++) {
            for (int col2 = 0; col2 < c; col2++) {
                dp[r - 1][col1][col2] = col1 == col2 ? grid[r - 1][col1] : grid[r - 1][col1] + grid[r - 1][col2];
            }
        }
        for (int row = r - 2; row >= 0; row--) {
            for (int col1 = 0; col1 < c; col1++) {
                for (int col2 = 0; col2 < c; col2++) {
                    int best = Integer.MIN_VALUE;
                    for (int d1 = -1; d1 <= 1; d1++) {
                        for (int d2 = -1; d2 <= 1; d2++) {
                            int p1 = col1 + d1, p2 = col2 + d2;
                            if (p1 < 0 || p1 >= c || p2 < 0 || p2 >= c) continue;
                            best = Math.max(best, dp[row + 1][p1][p2]);
                        }
                    }
                    int here = col1 == col2 ? grid[row][col1] : grid[row][col1] + grid[row][col2];
                    dp[row][col1][col2] = here + best;
                }
            }
        }
        return dp[0][0][c - 1];
    }
}

