class Solution {
    Boolean[][] memo;

    boolean isSubsetSum(int[] arr, int target) {
        memo = new Boolean[arr.length][target + 1];
        return can(arr, 0, target);
    }

    boolean can(int[] arr, int i, int sum) {
        if (sum == 0) return true;
        if (i == arr.length || sum < 0) return false;
        if (memo[i][sum] != null) return memo[i][sum];
        boolean take = arr[i] <= sum && can(arr, i + 1, sum - arr[i]);
        return memo[i][sum] = take || can(arr, i + 1, sum);
    }
}

