public class Solution {
    private const int INF = 1000000000;
    private int?[] memo;

    public int MinCoins(int[] coins, int amount) {
        memo = new int?[amount + 1];
        int ans = Solve(coins, amount);
        return ans >= INF ? -1 : ans;
    }

    private int Solve(int[] coins, int rem) {
        if (rem == 0) return 0;
        if (memo[rem] != null) return memo[rem].Value;
        int best = INF;
        foreach (int c in coins) if (c <= rem) best = Math.Min(best, 1 + Solve(coins, rem - c));
        memo[rem] = best;
        return best;
    }
}

