class Solution {
    Long[][] memo;

    long countWays(int[] coins, int amount) {
        memo = new Long[coins.length][amount + 1];
        return ways(coins, 0, amount);
    }

    long ways(int[] coins, int i, int rem) {
        if (rem == 0) return 1;
        if (i == coins.length) return 0;
        if (memo[i][rem] != null) return memo[i][rem];
        long res = ways(coins, i + 1, rem);
        if (coins[i] <= rem) res += ways(coins, i, rem - coins[i]);
        return memo[i][rem] = res;
    }
}

