public class Solution {
    private long?[,] memo;

    public long CountWays(int[] coins, int amount) {
        memo = new long?[coins.Length, amount + 1];
        return Ways(coins, 0, amount);
    }

    private long Ways(int[] coins, int i, int rem) {
        if (rem == 0) return 1;
        if (i == coins.Length) return 0;
        if (memo[i, rem] != null) return memo[i, rem].Value;
        long res = Ways(coins, i + 1, rem);
        if (coins[i] <= rem) res += Ways(coins, i, rem - coins[i]);
        memo[i, rem] = res;
        return res;
    }
}

