class Solution {
    public int ninjaTraining(int[][] points) {
        Integer[][] memo = new Integer[points.length][4];
        return best(points, points.length - 1, 3, memo);
    }
    private int best(int[][] points, int day, int last, Integer[][] memo) {
        if (day == 0) {
            int top = 0;
            for (int task = 0; task < 3; task++) {
                if (task != last) top = Math.max(top, points[0][task]);
            }
            return top;
        }
        if (memo[day][last] != null) return memo[day][last];
        int top = 0;
        for (int task = 0; task < 3; task++) {
            if (task == last) continue;
            top = Math.max(top, points[day][task] + best(points, day - 1, task, memo));
        }
        memo[day][last] = top;
        return top;
    }
}

