    public int MinFallingPathSum(int[][] matrix) {
        int n = matrix.Length;
        int?[,] memo = new int?[n, n];
        int best = int.MaxValue;
        for (int c = 0; c < n; c++) best = Math.Min(best, Path(matrix, n - 1, c, memo));
        return best;
    }
    private int Path(int[][] matrix, int r, int c, int?[,] memo) {
        if (c < 0 || c >= matrix.Length) return int.MaxValue / 2;
        if (r == 0) return matrix[0][c];
        if (memo[r, c] != null) return memo[r, c].Value;
        int top = Math.Min(Path(matrix, r - 1, c - 1, memo), Path(matrix, r - 1, c, memo));
        top = Math.Min(top, Path(matrix, r - 1, c + 1, memo));
        memo[r, c] = matrix[r][c] + top;
        return memo[r, c].Value;
    }
}

