class Solution {
    public int minimumTotal(List<List<Integer>> triangle) {
        int n = triangle.size();
        Integer[][] memo = new Integer[n][n];
        return path(triangle, 0, 0, memo);
    }
    private int path(List<List<Integer>> triangle, int r, int c, Integer[][] memo) {
        if (r == triangle.size() - 1) return triangle.get(r).get(c);
        if (memo[r][c] != null) return memo[r][c];
        int best = Math.min(path(triangle, r + 1, c, memo), path(triangle, r + 1, c + 1, memo));
        return memo[r][c] = triangle.get(r).get(c) + best;
    }
}

