        int total = 0;
        for (int x : arr) total += x;
        boolean[] dp = new boolean[total + 1];
        dp[0] = true;
        for (int num : arr)
            for (int s = total; s >= num; s--)
                dp[s] = dp[s] || dp[s - num];
        int best = total;
        for (int s = 0; s <= total; s++)
            if (dp[s]) best = Math.min(best, Math.abs(total - 2 * s));
        return best;
    }
