class Solution {
    public int minCost(int n, int[] cuts) {
        int m = cuts.length;
        int[] points = new int[m + 2];
        for (int i = 0; i < m; i++) points[i + 1] = cuts[i];
        points[m + 1] = n;
        Arrays.sort(points);
        int[][] dp = new int[m + 2][m + 2];
        for (int len = 2; len <= m + 1; len++) {
            for (int left = 0; left + len <= m + 1; left++) {
                int right = left + len;
                int best = Integer.MAX_VALUE;
                for (int cut = left + 1; cut < right; cut++) {
                    best = Math.min(best, dp[left][cut] + dp[cut][right]);
                }
                if (best != Integer.MAX_VALUE) dp[left][right] = points[right] - points[left] + best;
            }
        }
        return dp[0][m + 1];
    }
}

