            long rt = solve(s, k + 1, j, 1), rf = solve(s, k + 1, j, 0);
            char op = s.charAt(k);
            if (op == '&') ways += want == 1 ? lt * rt : lt * rf + lf * rt + lf * rf;
            else if (op == '|') ways += want == 1 ? lt * rt + lt * rf + lf * rt : lf * rf;
            else ways += want == 1 ? lt * rf + lf * rt : lt * rt + lf * rf;
        }
