class Solution {
    int[] dijkstra(int n, int[][] edges, int src) {
        int[][] w = new int[n][n];
        for (int[] row : w) Arrays.fill(row, -1);
        for (int[] e : edges) {
            if (w[e[0]][e[1]] == -1 || e[2] < w[e[0]][e[1]]) {
                w[e[0]][e[1]] = e[2];
                w[e[1]][e[0]] = e[2];
            }
        }
        int[] dist = new int[n];
        boolean[] done = new boolean[n];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[src] = 0;
        for (int step = 0; step < n; step++) {
            int node = -1;
            for (int i = 0; i < n; i++)
                if (!done[i] && (node == -1 || dist[i] < dist[node])) node = i;
            if (node == -1 || dist[node] == Integer.MAX_VALUE) break;
            done[node] = true;
            for (int j = 0; j < n; j++)
                if (!done[j] && w[node][j] != -1 && dist[node] + w[node][j] < dist[j])
                    dist[j] = dist[node] + w[node][j];
        }
        return dist;
    }
}

