class Solution {
    List<List<Integer>> traversal(int n, int[][] edges, int src) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }
        List<Integer> bfsOrder = new ArrayList<>();
        boolean[] seen = new boolean[n];
        Queue<Integer> queue = new LinkedList<>();
        queue.add(src);
        seen[src] = true;
        while (!queue.isEmpty()) {
            int node = queue.poll();
            bfsOrder.add(node);
            for (int next : adj.get(node))
                if (!seen[next]) {
                    seen[next] = true;
                    queue.add(next);
                }
        }
        List<Integer> dfsOrder = new ArrayList<>();
        boolean[] visited = new boolean[n];
        walk(src, adj, visited, dfsOrder);
        List<List<Integer>> res = new ArrayList<>();
        res.add(bfsOrder);
        res.add(dfsOrder);
        return res;
    }

    void walk(int node, List<List<Integer>> adj, boolean[] visited, List<Integer> order) {
        visited[node] = true;
        order.add(node);
        for (int next : adj.get(node))
            if (!visited[next]) walk(next, adj, visited, order);
    }
}

