    int[][] floydWarshall(int n, int[][] graph) {
        int inf = 1000000000;
        int[][] dist = new int[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++)
                dist[i][j] = graph[i][j] == -1 ? inf : graph[i][j];
            dist[i][i] = 0;
        }
        for (int k = 0; k < n; k++)
            for (int i = 0; i < n; i++)
                for (int j = 0; j < n; j++)
                    if (dist[i][k] + dist[k][j] < dist[i][j])
                        dist[i][j] = dist[i][k] + dist[k][j];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                if (dist[i][j] == inf) dist[i][j] = -1;
        return dist;
    }
}

