        Map<Integer, List<String>> merged = new HashMap<>();
        for (Map.Entry<String, Integer> e : owner.entrySet()) {
            int root = find(e.getValue());
            merged.computeIfAbsent(root, k -> new ArrayList<>()).add(e.getKey());
        }
        List<List<String>> res = new ArrayList<>();
        for (Map.Entry<Integer, List<String>> e : merged.entrySet()) {
            List<String> group = e.getValue();
            Collections.sort(group);
            group.add(0, accounts.get(e.getKey()).get(0));
            res.add(group);
        }
        return res;
    }

