        foreach (var e in merged) {
            var group = e.Value;
            group.Sort();
            group.Insert(0, accounts[e.Key][0]);
            res.Add(group);
        }
        return res;
    }

    private int Find(int x) {
        if (parent[x] != x) parent[x] = Find(parent[x]);
