class Solution {
    List<Integer> union(int[] a, int[] b) {
        List<Integer> res = new ArrayList<>();
        int i = 0, j = 0;
        while (i < a.length && j < b.length) {
            if (a[i] < b[j]) addDistinct(res, a[i++]);
            else if (a[i] > b[j]) addDistinct(res, b[j++]);
            else {
                addDistinct(res, a[i]);
                i++;
                j++;
            }
        }
        while (i < a.length) addDistinct(res, a[i++]);
        while (j < b.length) addDistinct(res, b[j++]);
        return res;
    }

    void addDistinct(List<Integer> res, int value) {
        if (res.isEmpty() || res.get(res.size() - 1) != value) res.add(value);
    }
}

