        for (int num : nums) {
            if (num == cand1) count1++;
            else if (num == cand2) count2++;
        }
        List<Integer> res = new ArrayList<>();
        int threshold = nums.length / 3;
        if (count1 > threshold) res.add(cand1);
        if (count2 > threshold) res.add(cand2);
        return res;
    }
}

