class Solution {
    public int maxLength(int[] nums) {
        Map<Integer, Integer> first = new HashMap<>();
        int sum = 0, best = 0;
        for (int i = 0; i < nums.length; i++) {
            sum += nums[i];
            if (sum == 0) best = i + 1;
            if (first.containsKey(sum)) {
                best = Math.max(best, i - first.get(sum));
            } else {
                first.put(sum, i);
            }
        }
        return best;
    }
}

