class Solution {
    public void merge(int[] a, int m, int[] b, int n) {
        int len = m + n;
        int gap = (len + 1) / 2;
        while (gap > 0) {
            int left = 0, right = left + gap;
            while (right < len) {
                if (left < m && right < m) compareSwap(a, a, left, right);
                else if (left < m) compareSwap(a, b, left, right - m);
                else compareSwap(b, b, left - m, right - m);
                left++;
                right++;
            }
            if (gap == 1) break;
            gap = (gap + 1) / 2;
        }
    }
    private void compareSwap(int[] x, int[] y, int i, int j) {
        if (x[i] > y[j]) {
            int temp = x[i];
            x[i] = y[j];
            y[j] = temp;
        }
    }
}

