class Solution {
    public int[] findTwoElement(int[] nums) {
        int xor = 0;
        for (int i = 0; i < nums.length; i++) xor ^= nums[i] ^ (i + 1);
        int bit = xor & -xor;
        int group1 = 0, group2 = 0;
        for (int i = 0; i < nums.length; i++) {
            int value = nums[i];
            if ((value & bit) != 0) group1 ^= value;
            else group2 ^= value;
            int natural = i + 1;
            if ((natural & bit) != 0) group1 ^= natural;
            else group2 ^= natural;
        }
        int repeating = group1, missing = group2;
        for (int num : nums) {
            if (num == group1) {
                repeating = group1;
                missing = group2;
                break;
            }
        }
        return new int[] { repeating, missing };
    }
}

