class Solution {
    public long inversionCount(long[] arr) {
        return mergeSort(arr, new long[arr.length], 0, arr.length - 1);
    }
    private long mergeSort(long[] arr, long[] buffer, int left, int right) {
        if (left >= right) return 0;
        int mid = (left + right) / 2;
        long count = mergeSort(arr, buffer, left, mid) + mergeSort(arr, buffer, mid + 1, right);
        int i = left, j = mid + 1, k = left;
        while (i <= mid && j <= right) {
            if (arr[i] <= arr[j]) {
                buffer[k++] = arr[i++];
            } else {
                count += mid - i + 1;
                buffer[k++] = arr[j++];
            }
        }
        while (i <= mid) buffer[k++] = arr[i++];
        while (j <= right) buffer[k++] = arr[j++];
        for (int x = left; x <= right; x++) arr[x] = buffer[x];
        return count;
    }
}

