class Solution {
    public int reversePairs(int[] nums) {
        return mergeSort(nums, new int[nums.length], 0, nums.length - 1);
    }
    private int mergeSort(int[] arr, int[] buffer, int left, int right) {
        if (left >= right) return 0;
        int mid = (left + right) / 2;
        int count = mergeSort(arr, buffer, left, mid) + mergeSort(arr, buffer, mid + 1, right);
        int j = mid + 1;
        for (int i = left; i <= mid; i++) {
            while (j <= right && arr[i] > 2L * arr[j]) j++;
            count += j - (mid + 1);
        }
        int i2 = left;
        j = mid + 1;
        int k = left;
        while (i2 <= mid && j <= right) {
            buffer[k++] = arr[i2] <= arr[j] ? arr[i2++] : arr[j++];
        }
        while (i2 <= mid) buffer[k++] = arr[i2++];
        while (j <= right) buffer[k++] = arr[j++];
        for (int x = left; x <= right; x++) arr[x] = buffer[x];
        return count;
    }
}

