class Solution {
    Long[][] memo;

    long countPalindromicSubsequences(String s) {
        int n = s.length();
        memo = new Long[n][n];
        return solve(s, 0, n - 1);
    }

    long solve(String s, int i, int j) {
        if (i > j) return 0;
        if (i == j) return 1;
        if (memo[i][j] != null) return memo[i][j];
        long result;
        if (s.charAt(i) == s.charAt(j))
            result = solve(s, i + 1, j) + solve(s, i, j - 1) + 1;
        else
            result = solve(s, i + 1, j) + solve(s, i, j - 1) - solve(s, i + 1, j - 1);
        memo[i][j] = result;
        return result;
    }
}

