                node = node.child[word.charAt(i) - 'a'];
                if (!node.isEnd) {
                    valid = false;
                    break;
                }
            }
            if (valid && (word.length() > answer.length()
                    || (word.length() == answer.length() && word.compareTo(answer) < 0)))
                answer = word;
