class Solution {
    static class Node {
        Node[] child = new Node[2];
    }

    public int findMaximumXOR(int[] nums) {
        Node root = new Node();
        for (int num : nums) insert(root, num);
        int answer = 0;
        for (int num : nums) answer = Math.max(answer, maxXor(root, num));
        return answer;
    }

    private void insert(Node root, int num) {
        Node node = root;
        for (int bit = 31; bit >= 0; bit--) {
            int b = (num >>> bit) & 1;
            if (node.child[b] == null) node.child[b] = new Node();
            node = node.child[b];
        }
    }

    private int maxXor(Node root, int num) {
        Node node = root;
        int result = 0;
        for (int bit = 31; bit >= 0; bit--) {
            int b = (num >>> bit) & 1;
            int opposite = b ^ 1;
            if (node.child[opposite] != null) {
                result |= 1 << bit;
                node = node.child[opposite];
            } else {
                node = node.child[b];
            }
        }
        return result;
    }
}

