    public TreeNode deleteNodeRecursive(TreeNode root, int key) {
        if (root == null) return null;
        if (key < root.val) root.left = deleteNodeRecursive(root.left, key);
        else if (key > root.val) root.right = deleteNodeRecursive(root.right, key);
        else {
