        return isValidBSTBrute(root.left) && isValidBSTBrute(root.right);
    }

    private boolean allLess(TreeNode node, int limit) {
        if (node == null) return true;
        if (node.val >= limit) return false;
        return allLess(node.left, limit) && allLess(node.right, limit);
    }

    private boolean allGreater(TreeNode node, int limit) {
        if (node == null) return true;
        if (node.val <= limit) return false;
        return allGreater(node.left, limit) && allGreater(node.right, limit);
    }
}

