class Solution {
    public List<Integer> mergeBSTs(TreeNode root1, TreeNode root2) {
        List<Integer> result = new ArrayList<>();
        Deque<TreeNode> stack1 = new ArrayDeque<>();
        Deque<TreeNode> stack2 = new ArrayDeque<>();
        pushLeft(stack1, root1);
        pushLeft(stack2, root2);
        while (!stack1.isEmpty() || !stack2.isEmpty()) {
            Deque<TreeNode> source;
            if (stack1.isEmpty()) source = stack2;
            else if (stack2.isEmpty()) source = stack1;
            else source = stack1.peek().val <= stack2.peek().val ? stack1 : stack2;
            TreeNode node = source.pop();
            result.add(node.val);
            pushLeft(source, node.right);
        }
        return result;
    }

    private void pushLeft(Deque<TreeNode> stack, TreeNode node) {
        while (node != null) {
            stack.push(node);
            node = node.left;
        }
    }
}

