    public boolean twoSumBST(TreeNode root, int k) {
        Deque<TreeNode> asc = new ArrayDeque<>();
        Deque<TreeNode> desc = new ArrayDeque<>();
        pushLeft(asc, root);
        pushRight(desc, root);
        while (!asc.isEmpty() && !desc.isEmpty()) {
            TreeNode low = asc.peek();
            TreeNode high = desc.peek();
            if (low == high) return false;
            int sum = low.val + high.val;
            if (sum == k) return true;
            if (sum < k) pushLeft(asc, asc.pop().right);
            else pushRight(desc, desc.pop().left);
        }
        return false;
    }

    private void pushLeft(Deque<TreeNode> stack, TreeNode node) {
        while (node != null) {
            stack.push(node);
            node = node.left;
        }
    }

    private void pushRight(Deque<TreeNode> stack, TreeNode node) {
        while (node != null) {
            stack.push(node);
            node = node.right;
        }
    }
}

