class Solution {
    static class Info {
        boolean isBST;
        int size;
        int min;
        int max;

        Info(boolean isBST, int size, int min, int max) {
            this.isBST = isBST;
            this.size = size;
            this.min = min;
            this.max = max;
        }
    }

    public int largestBST(TreeNode root) {
        return solve(root).size;
    }

    private Info solve(TreeNode node) {
        if (node == null) return new Info(true, 0, Integer.MAX_VALUE, Integer.MIN_VALUE);
        Info left = solve(node.left);
        Info right = solve(node.right);
        if (left.isBST && right.isBST && left.max < node.val && node.val < right.min) {
            return new Info(true, left.size + right.size + 1, Math.min(node.val, left.min), Math.max(node.val, right.max));
        }
        return new Info(false, Math.max(left.size, right.size), Integer.MIN_VALUE, Integer.MAX_VALUE);
    }
}

